"""
Flask API for task management with JWT authentication.

MODELS:
- User: id (int, auto), username (str, unique), password_hash (str)
- Task: id (int, auto), title (str), status (str, default 'pending'),
        created_at (datetime), owner_id (int) FK -> users.id

ENDPOINTS:
- POST /auth/register   create a user (JSON body: {username, password})
- POST /auth/login      return a JWT token (JSON body: {username, password})
- POST /tasks           create a task (JSON body: {title: str})
- GET  /tasks           list the authenticated user's tasks by created_at desc
- GET  /tasks/{id}      get a single task owned by the user
- PUT  /tasks/{id}      update task title and/or status

AUTH:
- All /tasks/* endpoints require a valid JWT in the Authorization header
  as "Bearer <token>". Missing/invalid tokens return 401.
- Each user only sees/edits their own tasks.

STORAGE:
- SQLite. Schema is initialized on startup. A migration step adds the
  tasks.owner_id column when upgrading an existing database without
  destroying existing data.
"""

import os
import sqlite3
from functools import wraps
from datetime import datetime, timedelta, timezone

import jwt
from celery import Celery
from flask import Flask, jsonify, request
from werkzeug.security import check_password_hash, generate_password_hash

import celery_config
from repositories import TaskRepository, UserRepository

app = Flask(__name__)

DATABASE = os.environ.get("DATABASE", "tasks.db")
app.config.setdefault("SECRET_KEY", os.environ.get("SECRET_KEY", "dev-secret-key"))
app.config.setdefault("JWT_EXPIRATION_HOURS", 24)


def create_celery():
    celery_app = Celery(
        __name__,
        broker=celery_config.broker_url,
        backend=celery_config.result_backend,
        include=["app"],
    )
    celery_app.conf.update(
        task_routes=celery_config.task_routes,
        task_serializer=celery_config.task_serializer,
        result_serializer=celery_config.result_serializer,
        accept_content=celery_config.accept_content,
        timezone=celery_config.timezone,
        enable_utc=celery_config.enable_utc,
    )
    return celery_app


celery = create_celery()


@celery.task(name="app.send_notification_email")
def send_notification_email(user_email, task_title):
    message = f"Mock email sent to {user_email}: your task '{task_title}' is completed."
    print(message)
    app.logger.info(message)
    return message


def user_email_from_row(user):
    if "email" in user.keys() and user["email"]:
        return user["email"]
    return user["username"]


def get_db():
    conn = sqlite3.connect(app.config.get("DATABASE", DATABASE))
    conn.row_factory = sqlite3.Row
    return conn


def init_db():
    with get_db() as conn:
        conn.execute("PRAGMA foreign_keys = ON")
        conn.execute(
            """
            CREATE TABLE IF NOT EXISTS users (
                id INTEGER PRIMARY KEY AUTOINCREMENT,
                username TEXT NOT NULL UNIQUE,
                password_hash TEXT NOT NULL
            );
            """
        )
        conn.execute(
            """
            CREATE TABLE IF NOT EXISTS tasks (
                id INTEGER PRIMARY KEY AUTOINCREMENT,
                title TEXT NOT NULL,
                status TEXT NOT NULL DEFAULT 'pending',
                created_at DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP
            );
            """
        )
        columns = [r["name"] for r in conn.execute("PRAGMA table_info(tasks)")]
        if "owner_id" not in columns:
            conn.execute(
                "ALTER TABLE tasks ADD COLUMN owner_id INTEGER REFERENCES users(id)"
            )
        conn.commit()


def create_token(user_id, username):
    payload = {
        "sub": user_id,
        "username": username,
        "exp": datetime.now(timezone.utc)
        + timedelta(hours=app.config["JWT_EXPIRATION_HOURS"]),
    }
    return jwt.encode(payload, app.config["SECRET_KEY"], algorithm="HS256")


def get_current_user():
    header = request.headers.get("Authorization", "")
    if not header.startswith("Bearer "):
        return None
    token = header[len("Bearer "):]
    try:
        payload = jwt.decode(token, app.config["SECRET_KEY"], algorithms=["HS256"])
    except jwt.PyJWTError:
        return None
    user_id = payload.get("sub")
    if user_id is None:
        return None
    return UserRepository(get_db).get(user_id)


def require_auth(fn):
    @wraps(fn)
    def wrapper(*args, **kwargs):
        user = get_current_user()
        if user is None:
            return jsonify({"error": "authentication required"}), 401
        request.current_user = user
        return fn(*args, **kwargs)

    return wrapper


@app.route("/auth/register", methods=["POST"])
def register():
    data = request.get_json(silent=True) or {}
    username = data.get("username")
    password = data.get("password")
    if username is None or not str(username).strip():
        return jsonify({"error": "username is required"}), 400
    if password is None or not str(password):
        return jsonify({"error": "password is required"}), 400
    username = str(username).strip()
    user_repo = UserRepository(get_db)
    if user_repo.find_by_username(username) is not None:
        return jsonify({"error": "username already taken"}), 409
    user = user_repo.create(
        username=username, password_hash=generate_password_hash(str(password))
    )
    return jsonify(user_repo.to_dict(user)), 201


@app.route("/auth/login", methods=["POST"])
def login():
    data = request.get_json(silent=True) or {}
    username = data.get("username")
    password = data.get("password")
    if username is None or password is None:
        return jsonify({"error": "username and password are required"}), 400
    user_repo = UserRepository(get_db)
    user = user_repo.find_by_username(username)
    if user is None or not check_password_hash(user["password_hash"], str(password)):
        return jsonify({"error": "invalid credentials"}), 401
    token = create_token(user["id"], user["username"])
    return jsonify({"token": token, "user": user_repo.to_dict(user)}), 200


@app.route("/tasks", methods=["POST"])
@require_auth
def create_task():
    user = request.current_user
    data = request.get_json(silent=True) or {}
    title = data.get("title")
    if title is None or not str(title).strip():
        return jsonify({"error": "title is required"}), 400
    title = str(title).strip()
    status = data.get("status") or "pending"
    task_repo = TaskRepository(get_db)
    task = task_repo.create(title=title, status=status, owner_id=user["id"])
    return jsonify(task_repo.to_dict(task)), 201


@app.route("/tasks", methods=["GET"])
@require_auth
def list_tasks():
    user = request.current_user
    task_repo = TaskRepository(get_db)
    tasks = task_repo.find_by_owner(user["id"])
    return jsonify([task_repo.to_dict(t) for t in tasks])


@app.route("/tasks/<int:task_id>", methods=["GET"])
@require_auth
def get_task(task_id):
    user = request.current_user
    task_repo = TaskRepository(get_db)
    task = task_repo.find_by_id_and_owner(task_id, user["id"])
    if task is None:
        return jsonify({"error": "task not found"}), 404
    return jsonify(task_repo.to_dict(task))


@app.route("/tasks/<int:task_id>", methods=["PUT"])
@require_auth
def update_task(task_id):
    user = request.current_user
    data = request.get_json(silent=True) or {}
    task_repo = TaskRepository(get_db)
    task = task_repo.find_by_id_and_owner(task_id, user["id"])
    if task is None:
        return jsonify({"error": "task not found"}), 404
    previous_status = task["status"]
    title = data.get("title", task["title"])
    status = data.get("status", task["status"])
    if title is None or not str(title).strip():
        return jsonify({"error": "title is required"}), 400
    task = task_repo.update(task_id, title=str(title).strip(), status=status)
    if status == "completed" and previous_status != "completed":
        try:
            send_notification_email.delay(
                user_email_from_row(user), task["title"]
            )
        except Exception as exc:
            app.logger.error(
                "Failed to enqueue completion notification for task %s: %s",
                task_id,
                exc,
            )
    return jsonify(task_repo.to_dict(task))


init_db()


if __name__ == "__main__":
    init_db()
    app.run(debug=True)

"""Repository pattern data access layer for the task management API.

All SQLite access lives in this module. Route handlers and other
application code interact with repositories instead of issuing raw SQL.
"""

from abc import ABC, abstractmethod


class BaseRepository(ABC):
    """Abstract base repository providing common CRUD operations.

    Concrete subclasses declare the table they manage and how to convert
    a database row into a public-facing dictionary.
    """

    def __init__(self, db_factory):
        self.db_factory = db_factory

    @property
    @abstractmethod
    def table(self):
        """Name of the database table managed by this repository."""

    @abstractmethod
    def to_dict(self, row):
        """Convert a database row into a public-facing dictionary."""

    def _get_conn(self):
        return self.db_factory()

    def get(self, row_id):
        with self._get_conn() as conn:
            return conn.execute(
                f"SELECT * FROM {self.table} WHERE id = ?", (row_id,)
            ).fetchone()

    def list_all(self):
        with self._get_conn() as conn:
            return conn.execute(f"SELECT * FROM {self.table}").fetchall()

    def create(self, **fields):
        columns = ", ".join(fields)
        placeholders = ", ".join("?" for _ in fields)
        values = tuple(fields.values())
        with self._get_conn() as conn:
            cursor = conn.execute(
                f"INSERT INTO {self.table} ({columns}) VALUES ({placeholders})",
                values,
            )
            conn.commit()
            return conn.execute(
                f"SELECT * FROM {self.table} WHERE id = ?", (cursor.lastrowid,)
            ).fetchone()

    def update(self, row_id, **fields):
        assignments = ", ".join(f"{column} = ?" for column in fields)
        values = tuple(fields.values()) + (row_id,)
        with self._get_conn() as conn:
            conn.execute(
                f"UPDATE {self.table} SET {assignments} WHERE id = ?", values
            )
            conn.commit()
            return conn.execute(
                f"SELECT * FROM {self.table} WHERE id = ?", (row_id,)
            ).fetchone()

    def delete(self, row_id):
        with self._get_conn() as conn:
            conn.execute(f"DELETE FROM {self.table} WHERE id = ?", (row_id,))
            conn.commit()
        return None


class UserRepository(BaseRepository):
    """Repository for the users table."""

    @property
    def table(self):
        return "users"

    def to_dict(self, row):
        return {
            "id": row["id"],
            "username": row["username"],
        }

    def find_by_username(self, username):
        with self._get_conn() as conn:
            return conn.execute(
                "SELECT * FROM users WHERE username = ?", (username,)
            ).fetchone()


class TaskRepository(BaseRepository):
    """Repository for the tasks table."""

    @property
    def table(self):
        return "tasks"

    def to_dict(self, row):
        return {
            "id": row["id"],
            "title": row["title"],
            "status": row["status"],
            "created_at": row["created_at"],
            "owner_id": row["owner_id"],
        }

    def find_by_owner(self, owner_id):
        with self._get_conn() as conn:
            return conn.execute(
                "SELECT * FROM tasks WHERE owner_id = ? "
                "ORDER BY created_at DESC, id DESC",
                (owner_id,),
            ).fetchall()

    def find_by_id_and_owner(self, task_id, owner_id):
        with self._get_conn() as conn:
            return conn.execute(
                "SELECT * FROM tasks WHERE id = ? AND owner_id = ?",
                (task_id, owner_id),
            ).fetchone()

